ns','post format archive titleQuotes'=>'Citations','post format archive titleVideos'=>'Vidéos','post type archive title prefixArchives:'=>'Archives :','posts split into pages'=>'posts répartis sur plusieurs pages','posts split into pages, bbPress topics'=>'posts répartis sur plusieurs pages, thèmes bbPress','quarterly'=>'trimestriel','single blog posts'=>'articles de blog individuels','tag archive title prefixTag:'=>'Étiquette :','taxonomy term archive title prefix%s:'=>'%s :','weekly'=>'hebdomadaire','yearly archives date formatY'=>'Y','— No Change —'=>'— Pas de changement —','⚠️ some failed in last run'=>'⚠️ Échec de certains envois lors de la dernière exécution','✅ all emails in last run sent'=>'✅ Tous les e-mails ont été envoyés lors de la dernière exécution','❌ all failed in last run'=>'❌ tous les envois ont échoué lors de la dernière exécution']];
